  selector: 'app-root',
  templateUrl: './app.component.html',
  styleUrls: ['./app.component.scss'],
})
export class AppComponent {}
<div class="app-shell">
  <app-route-panel></app-route-panel>
  <app-map></app-map>
  <app-toast></app-toast>
</div>
